itemEvidence.finalSql:
SELECT order_id,payment_sequential,payment_installments
FROM order_payments WHERE payment_installments IS NOT NULL
ORDER BY payment_installments DESC,order_id,payment_sequential LIMIT 1;

SELECT p.product_id, p.product_photos_qty, COUNT(*) AS sold
FROM order_items oi JOIN products p ON p.product_id = oi.product_id
GROUP BY 1, 2 ORDER BY sold DESC NULLS LAST,p.product_id LIMIT 10;
